clean_output:
if system_wide:
    if not is_root():
        raise PermissionError("Must be root to add to system-wide startup.")
    path = "/etc/rc.local"
else:
    path = os.path.join(os.path.expanduser("~"), ".config", "autostart")

with open(path, "a") as f:
    f.write("\n")
    f.write("# {}\n".format(name))
    f.write("{} &\n".format(command))
